insert into public.df_news (id, data) values
  ('news-seed-01', $j${"id": "news-seed-01", "author_id": "user-admin-1", "author_name": "Responsable", "title": "Bienvenue sur Gestion Pro", "text": "Bienvenue dans votre espace de travail. Vous y trouvez vos missions, le calendrier, la messagerie et ce fil d’actualité. Prenez le temps de compléter votre profil avec une photo : c’est la première étape.", "created_at": "2026-10-01T08:00:00.000Z", "pinned": true, "loves": [], "comments": [], "shares": 0}$j$::jsonb),
  ('news-seed-02', $j${"id": "news-seed-02", "author_id": "user-admin-1", "author_name": "Responsable", "title": "Règle d’or de la saisie : zéro champ vide", "text": "Avant d’envoyer une fiche, relisez-la une fois. Un champ vide ou un numéro mal recopié fait refuser la mission. Mieux vaut une minute de plus que de refaire tout un lot.", "created_at": "2026-10-02T07:00:00.000Z", "pinned": false, "loves": [], "comments": [], "shares": 0}$j$::jsonb),
  ('news-seed-03', $j${"id": "news-seed-03", "author_id": "user-admin-1", "author_name": "Responsable", "title": "Comment fonctionne une mission", "text": "Une mission suit toujours le même chemin : à faire, en cours, à valider, puis validée ou refusée. En cas de refus, le motif est indiqué : lisez-le, corrigez, puis renvoyez.", "created_at": "2026-10-03T06:00:00.000Z", "pinned": false, "loves": [], "comments": [], "shares": 0}$j$::jsonb),
  ('news-seed-04', $j${"id": "news-seed-04", "author_id": "user-admin-1", "author_name": "Responsable", "title": "Objectif de la semaine", "text": "Cette semaine, l’objectif d’équipe est de terminer tous les lots de saisie en cours et de passer la relecture qualité avant vendredi. Merci à chacun pour son sérieux.", "created_at": "2026-10-04T05:00:00.000Z", "pinned": false, "loves": [], "comments": [], "shares": 0}$j$::jsonb),
  ('news-seed-05', $j${"id": "news-seed-05", "author_id": "user-admin-1", "author_name": "Responsable", "title": "Astuce Excel : gagner du temps", "text": "Utilisez Ctrl+C / Ctrl+V pour copier, Ctrl+Z pour annuler, et la touche Tab pour passer à la cellule suivante. Trier une colonne permet aussi de repérer les doublons très vite.", "created_at": "2026-10-05T04:00:00.000Z", "pinned": false, "loves": [], "comments": [], "shares": 0}$j$::jsonb),
  ('news-seed-06', $j${"id": "news-seed-06", "author_id": "user-admin-1", "author_name": "Responsable", "title": "Rappel : les vacations Jour et Nuit", "text": "Connectez-vous à l’heure de votre vacation. Les horaires sont réglés par le responsable, avec une petite tolérance. Prévenez par la messagerie en cas de retard ou d’absence.", "created_at": "2026-10-06T03:00:00.000Z", "pinned": false, "loves": [], "comments": [], "shares": 0}$j$::jsonb),
  ('news-seed-07', $j${"id": "news-seed-07", "author_id": "user-admin-1", "author_name": "Responsable", "title": "Nouveaux types de mission", "text": "Les missions sont maintenant classées en cinq types : saisie de fiches, contrôle qualité, tâche administrative, demande d’aide et tâche web. Chaque type a ses propres consignes.", "created_at": "2026-10-07T02:00:00.000Z", "pinned": false, "loves": [], "comments": [], "shares": 0}$j$::jsonb),
  ('news-seed-08', $j${"id": "news-seed-08", "author_id": "user-admin-1", "author_name": "Responsable", "title": "Contrôle qualité : comment ça se passe", "text": "Le contrôle qualité consiste à relire le travail des autres : champs vides, doublons, mauvais formats. Si tout est correct, on valide. Sinon, on refuse avec un motif clair et poli.", "created_at": "2026-10-08T01:00:00.000Z", "pinned": false, "loves": [], "comments": [], "shares": 0}$j$::jsonb),
  ('news-seed-09', $j${"id": "news-seed-09", "author_id": "user-admin-1", "author_name": "Responsable", "title": "Protégez votre mot de passe", "text": "Ne partagez jamais votre mot de passe, même avec un collègue. Changez-le dès votre première connexion et choisissez-en un que vous n’utilisez nulle part ailleurs.", "created_at": "2026-10-09T00:00:00.000Z", "pinned": false, "loves": [], "comments": [], "shares": 0}$j$::jsonb),
  ('news-seed-10', $j${"id": "news-seed-10", "author_id": "user-admin-1", "author_name": "Responsable", "title": "Merci pour votre travail", "text": "Merci à toute l’équipe pour le sérieux et la ponctualité de ces derniers jours. N’hésitez pas à réagir et à commenter les publications : vos retours nous aident à améliorer l’outil.", "created_at": "2026-10-09T23:00:00.000Z", "pinned": false, "loves": [], "comments": [], "shares": 0}$j$::jsonb)
